const fs = require('fs');
const { inflate, inflateRawSync } = require('zlib');

const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

// Manual ZIP parsing to find word/document.xml
let offset = 0;
const entries = [];
while (offset < buf.length - 4) {
    const sig = buf.readUInt32LE(offset);
    if (sig !== 0x04034b50) break; // local file header signature

    const compressionMethod = buf.readUInt16LE(offset + 8);
    const compressedSize = buf.readUInt32LE(offset + 18);
    const uncompressedSize = buf.readUInt32LE(offset + 22);
    const nameLen = buf.readUInt16LE(offset + 26);
    const extraLen = buf.readUInt16LE(offset + 28);
    const name = buf.slice(offset + 30, offset + 30 + nameLen).toString('utf8');
    const dataStart = offset + 30 + nameLen + extraLen;

    if (name === 'word/document.xml') {
        const compressed = buf.slice(dataStart, dataStart + compressedSize);
        let data;
        if (compressionMethod === 0) {
            data = compressed;
        } else {
            data = inflateRawSync(compressed);
        }
        const xml = data.toString('utf8');

        // Extract text by paragraphs
        const paragraphs = xml.split(/<\/w:p>/);
        for (const para of paragraphs) {
            let line = '';
            const tRegex = /<w:t[^>]*>([\s\S]*?)<\/w:t>/g;
            let m;
            while ((m = tRegex.exec(para)) !== null) {
                line += m[1];
            }
            if (line.trim()) console.log(line);
        }
        break;
    }

    offset = dataStart + compressedSize;
}
